package com.yeyamo_mobile.api.notification_service.infrastructure.channel;
import org.springframework.beans.factory.annotation.Value;import org.springframework.mail.SimpleMailMessage;import org.springframework.mail.javamail.JavaMailSender;import org.springframework.stereotype.Component;import com.yeyamo_mobile.api.notification_service.application.port.ChannelSender;import com.yeyamo_mobile.api.notification_service.domain.NotificationChannel;
@Component public class EmailChannelSender implements ChannelSender{private final JavaMailSender mail;private final String from;public EmailChannelSender(JavaMailSender m,@Value("${notification.email.from:no-reply@yeyamo.app}")String f){mail=m;from=f;}public NotificationChannel channel(){return NotificationChannel.EMAIL;}public void send(String destination,String subject,String body,String data){if(destination==null||destination.isBlank())throw new IllegalArgumentException("Email destination is missing");SimpleMailMessage message=new SimpleMailMessage();message.setFrom(from);message.setTo(destination);message.setSubject(subject);message.setText(body);mail.send(message);}}
